function createStrategy() {
  'use strict';

  // Opening sequence uses cheap all-purpose bolts while the economy ramps,
  // then the board hardens into a broad cannon line with dedicated flak cover.
  var BUILD_ORDER = [13, 8, 4, 0, 3, 11, 6, 1, 2, 14, 5, 15, 9, 10, 7, 12];
  var BUILD_TYPES = ['bolt', 'cannon', 'bolt', 'flak', 'bolt', 'cannon', 'cannon', 'flak', 'flak', 'flak', 'cannon', 'flak', 'cannon', 'cannon', 'cannon', 'bolt'];
  var FINAL_TYPES = ['flak', 'flak', 'flak', 'cannon', 'cannon', 'cannon', 'cannon', 'cannon', 'cannon', 'cannon', 'cannon', 'cannon', 'cannon', 'cannon', 'flak', 'flak'];
  var UPGRADE_ORDER = [13, 3, 7, 8, 6, 9, 1, 4, 2, 5, 12, 10, 11, 0, 14, 15];
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };

  return {
    plan: function (s) {
      var acts = [];
      var gold = s.gold;
      var have = {};

      for (var i = 0; i < s.slots.length; i++) {
        var sl = s.slots[i];
        if (sl.turret) {
          have[sl.slot] = { type: sl.turret.type, tier: sl.turret.tier, spent: sl.turret.spent };
        }
      }

      // Spend on new infrastructure first; the slot count is the hard cap.
      for (var b = 0; b < BUILD_ORDER.length && acts.length < 32; b++) {
        var bs = BUILD_ORDER[b];
        var bt = BUILD_TYPES[b];
        if (have[bs] || gold < COST[bt]) continue;
        acts.push({ op: 'build', slot: bs, type: bt });
        gold -= COST[bt];
        have[bs] = { type: bt, tier: 1, spent: COST[bt] };
      }

      // Raise tiers in a deliberate priority order, cheapest useful ranks first.
      while (acts.length < 32) {
        var targetSlot = -1;
        for (var u = 0; u < UPGRADE_ORDER.length; u++) {
          var us = UPGRADE_ORDER[u];
          var ut = have[us];
          if (ut && ut.tier < 3) { targetSlot = us; break; }
        }
        if (targetSlot < 0) break;
        var tt = have[targetSlot];
        var uc = COST[tt.type] * (tt.tier === 1 ? 1 : 2);
        if (gold < uc) break;
        acts.push({ op: 'upgrade', slot: targetSlot });
        gold -= uc;
        tt.tier += 1;
        tt.spent += uc;
      }

      // Once the war chest can afford a full reconstruction, replace the
      // opening bolts with the final mixed battery.
      if (acts.length < 32) {
        for (var c = 0; c < BUILD_ORDER.length && acts.length < 32; c++) {
          var cs = BUILD_ORDER[c];
          var ct = have[cs];
          if (!ct) continue;
          var ft = FINAL_TYPES[cs];
          if (ct.type === ft) continue;
          var refund = Math.floor(ct.spent * 70 / 100);
          var rebuild = COST[ft] * 4;
          if (gold + refund < rebuild) continue;
          acts.push({ op: 'sell', slot: cs });
          gold += refund;
          acts.push({ op: 'build', slot: cs, type: ft });
          gold -= COST[ft];
          acts.push({ op: 'upgrade', slot: cs });
          gold -= COST[ft];
          acts.push({ op: 'upgrade', slot: cs });
          gold -= COST[ft] * 2;
          have[cs] = { type: ft, tier: 3, spent: rebuild };
        }
      }

      return acts;
    },

    target: function (turret, candidates) {
      if (turret.type === 'cannon' || turret.type === 'flak') {
        // Splash batteries seek the densest knot in reach. Every extra body
        // inside the burst radius is worth far more than a single strong hit.
        var radius = turret.type === 'cannon' ? 90 : 70;
        var best = candidates[0];
        var bestCount = -1;
        for (var i = 0; i < candidates.length; i++) {
          var e = candidates[i];
          var count = 0;
          for (var j = 0; j < candidates.length; j++) {
            var o = candidates[j];
            var dx = o.x - e.x;
            var dy = o.y - e.y;
            if (dx * dx + dy * dy <= radius * radius) count++;
          }
          if (count > bestCount || (count === bestCount && e.remaining < best.remaining)) {
            bestCount = count;
            best = e;
          }
        }
        return best.id;
      }

      // Single-target guns finish the closest threat first, but menders and
      // splitters are pulled forward so their support value never compounds.
      var choice = candidates[0];
      var key = 1e18;
      for (var k = 0; k < candidates.length; k++) {
        var en = candidates[k];
        var v = en.remaining;
        if (en.type === 'mender') v -= 100000;
        else if (en.type === 'splitter') v -= 1000;
        if (v < key) { key = v; choice = en; }
      }
      return choice.id;
    }
  };
}

